//! Evora (EVORA-REV-111) : la table de tons du rendu d'Evora. Branchée depuis EVORA-REV-112 : sous le
//! prédicat du rendu, c'est la table du noyau par point (`finish::base_tone`, bras d'`Evora1`).
//!
//! Sous Evora, contraste, blancs et noirs agissent en EV de scène autour du gris moyen, sur l'image
//! que le pont de scène a menée en lumière de scène ([`super::bridge`]) :
//! - le contraste écarte les EV du pivot ; au-delà de sa portée (plus courte vers les ombres que
//!   vers les clairs) son gain de pente s'éteint ;
//! - les blancs déplacent les clairs, les noirs déplacent les ombres, chacun sur un passage lisse.
//!
//! La luminance de scène ainsi réglée finit par le pont de retour, qui tend vers le blanc sans
//! jamais couper. C'est la loi `tons` de la référence du rendu (evora1.py:141-153).
//!
//! La table est celle du moteur ([`ToneMap`], [`LUT_N`] nœuds de [`LUT_MIN_EV`] à [`LUT_MAX_EV`]
//! autour du gris), lue par [`ToneMap::apply`]. Deux choses la distinguent des tables de l'amont :
//! - elle stocke le pont de retour **sans sa borne à 1** : la valeur passe 1 au blanc de scène et
//!   tend vers `W`, un peu au-dessus. La borne vient après la lecture, chez qui lit la table. Bornée
//!   avant d'être stockée, la table aurait un coude au blanc de scène, que l'interpolation entre deux
//!   nœuds arrondit mal (`tests::tone_table_reads_within_tolerance` en porte le témoin) ;
//! - elle porte les nœuds de chroma du pont ([`Bridge::chroma`]) : [`ToneMap::chroma_scale`] reprend
//!   aux clairs la couleur que le pont leur a rendue à l'aller.
//!
//! Chaque nœud se calcule en double précision, comme dans la référence, puis s'arrondit en simple
//! précision. L'exposition n'entre pas ici : c'est un gain posé sur la scène avant la table.

use super::bridge::Bridge;
use super::{
    BLACKS_FROM, BLACKS_TO, CONTRAST_PIVOT, CONTRAST_SHOULDER, CONTRAST_TOE, GREY, K_BLACKS, K_CONTRAST, K_WHITES, WHITES_FROM, WHITES_TO, smooth,
};
use crate::tone::{LUT_MAX_EV, LUT_MIN_EV, LUT_N, ToneMap};

/// Evora (EVORA-REV-111) : la course d'un curseur de tons, de part et d'autre de zéro. Contraste,
/// blancs et noirs arrivent en −100..100, et la référence les divise par cette valeur avant de les
/// lire (evora1.py:145, 150 et 152).
const SLIDER_RANGE: f64 = 100.0;

/// Evora (EVORA-REV-111) : un EV de scène autour du gris moyen → le même EV réglé par le contraste,
/// les blancs puis les noirs (`tons`, evora1.py:144-152, sans son pont de retour). `contrast`,
/// `whites`, `blacks` en −100..100, comme les curseurs.
///
/// L'ordre fait partie de la loi : les blancs lisent l'EV déjà réglé par le contraste, les noirs
/// l'EV déjà réglé par les blancs. Un curseur à zéro ne touche pas l'EV. La loi est croissante pour
/// toute position des trois curseurs dans leur course : la table qui en sort l'est aussi
/// (`tests::tone_table_is_increasing_and_bounded`).
pub fn tone_ev(ev: f64, contrast: f64, whites: f64, blacks: f64) -> f64 {
    let ev = if contrast != 0.0 {
        let gain = (contrast / SLIDER_RANGE * K_CONTRAST).exp2();
        let x = ev - CONTRAST_PIVOT;
        let reach = if x < 0.0 { CONTRAST_TOE } else { CONTRAST_SHOULDER };
        ev + (gain - 1.0) * x / (1.0 + x.abs() / reach)
    } else {
        ev
    };
    let ev = if whites != 0.0 { ev + whites / SLIDER_RANGE * K_WHITES * smooth(WHITES_FROM, WHITES_TO, ev) } else { ev };
    if blacks != 0.0 { ev + blacks / SLIDER_RANGE * K_BLACKS * (1.0 - smooth(BLACKS_FROM, BLACKS_TO, ev)) } else { ev }
}

/// Evora (EVORA-REV-111) : la loi de tons entière, en double précision : un EV de scène autour du
/// gris moyen → la luminance d'affichage, **sans la borne à 1** (`tons`, evora1.py:141-153, dont la
/// sortie est cette valeur bornée à 1). [`tone_ev`], puis le pont de retour de `bridge`.
///
/// C'est la valeur que [`table`] stocke à chaque nœud. Le pont de retour s'écrit ici en double
/// précision : [`Bridge::to_display_unbounded`] est la même forme en simple précision, pour le
/// calcul par point.
pub fn tone_unbounded(bridge: &Bridge, ev: f64, contrast: f64, whites: f64, blacks: f64) -> f64 {
    let scene = GREY * tone_ev(ev, contrast, whites, blacks).exp2();
    let sn = scene.max(0.0).powf(bridge.n());
    bridge.w() * sn / (sn + bridge.q())
}

/// Evora (EVORA-REV-111) : la table de tons du rendu d'Evora pour ces trois curseurs (en −100..100),
/// sur le pont `bridge`. [`LUT_N`] nœuds régulièrement espacés en EV de [`LUT_MIN_EV`] à
/// [`LUT_MAX_EV`] autour du gris : à chacun, [`tone_unbounded`] arrondie en simple précision. Avec
/// elle, les nœuds de chroma du pont.
///
/// La table n'est pas bornée : qui la lit borne à 1 après [`ToneMap::apply`]. Aux réglages neutres,
/// elle défait le pont aller : une luminance d'affichage menée en scène par [`Bridge::to_scene`] se
/// relit à elle-même, à l'interpolation de la table près.
///
/// Sous [`LUT_MIN_EV`], [`ToneMap::apply`] prolonge la table en ligne droite (la valeur du premier
/// nœud, proportionnelle à la luminance), là où la loi continue en puissance (le pied du pont,
/// d'exposant `n`, que les curseurs modulent) : à −20 EV aux réglages neutres, la table rend 3,5 fois
/// la loi (1,1e-8 contre 3,3e-9). Écart de forme sans effet visible : au plus 0,54 code sur 16 bits
/// sur les 27 positions extrêmes des trois curseurs (mesuré hors moteur). Le plus petit code non nul
/// d'un fichier sur 16 bits tombe en scène à 1,6e-5, au-dessus du premier nœud (1,1e-5) : l'identité
/// au neutre n'en dépend pas. À ne pas prendre pour une régression.
pub fn table(bridge: &Bridge, contrast: f64, whites: f64, blacks: f64) -> ToneMap {
    let (low, high) = (f64::from(LUT_MIN_EV), f64::from(LUT_MAX_EV));
    let lut: Vec<f32> = (0..LUT_N)
        .map(|i| {
            let ev = low + (high - low) * i as f64 / (LUT_N - 1) as f64;
            tone_unbounded(bridge, ev, contrast, whites, blacks) as f32
        })
        .collect();
    ToneMap::from_parts(lut, *bridge.chroma())
}

